/**
 * A new project in the same workspace. Description, visibility, colour and lead
 * come from the source; status is active and dates are clear. Live issues are
 * copied only when asked, renumbered from 1, reset to a fresh start. One
 * `project.cloned` event is published — not `project.created` or `issue.created`.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const projectsUsed = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", projectsUsed)) {
    throw new Error(
      `Plan ${org.plan} allows ${projectsUsed} projects; upgrade to add another`,
    );
  }

  const includeIssues = input.includeIssues ?? true;
  const sources = includeIssues
    ? await issueRepo.listLiveIssuesByNumber(input.orgId, source.id)
    : [];

  if (
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sources.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  let issuesCopied = 0;
  for (const sourceIssue of sources) {
    issuesCopied += 1;
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: project.id,
        title: sourceIssue.title,
        description: sourceIssue.description,
        status,
        priority: sourceIssue.priority,
        assigneeId: null,
        parentId: null,
        estimate: sourceIssue.estimate,
        dueAt: sourceIssue.dueAt,
        labelIds: [...sourceIssue.labelIds],
      },
      actor.userId,
      issuesCopied,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}

